package com.example.simpleclient;
import com.fasterxml.jackson.databind.*; import javafx.application.Platform; import javafx.fxml.FXML; import javafx.scene.control.*; import javafx.scene.layout.*; import java.net.URI; import java.net.http.*;
public class AdminCustomersController { @FXML private VBox customerContainer; @FXML private Label statusLabel; private final HttpClient http=HttpClient.newHttpClient(); private final ObjectMapper mapper=new ObjectMapper(); @FXML private void initialize(){load();} @FXML private void refresh(){load();} private void load(){new Thread(()->{try{HttpRequest r=HttpRequest.newBuilder(URI.create("http://localhost:8080/api/admin/customers")).header("Authorization","Bearer "+AdminSession.getToken()).GET().build();HttpResponse<String>x=http.send(r,HttpResponse.BodyHandlers.ofString());JsonNode a=mapper.readTree(x.body());Platform.runLater(()->render(a));}catch(Exception e){Platform.runLater(()->statusLabel.setText("Unable to load customers"));}}).start();} private void render(JsonNode a){customerContainer.getChildren().clear();statusLabel.setText(a.size()+" registered customers");for(JsonNode c:a){VBox card=new VBox(5);card.getStyleClass().add("admin-customer-row");Label n=new Label(c.path("name").asText("Customer"));n.getStyleClass().add("admin-customer-name");Label m=new Label(c.path("email").asText("—")+"   •   "+c.path("phone").asText("No phone"));m.getStyleClass().add("admin-customer-meta");card.getChildren().addAll(n,m);customerContainer.getChildren().add(card);}} }
